ermittleKritischsteStation(messungen : Messung[], grenzwert : Double, stationIds : Integer[]) : Integer {
  Integer[] zaehler = new Integer[stationIds.length]
  for (int k = 0; k < stationIds.length; k++) { zaehler[k] = 0 }
  for (int i = 0; i < messungen.length; i++) {
    if (messungen[i].getWert() > grenzwert) {
      for (int k = 0; k < stationIds.length; k++) {
        if (messungen[i].getStationId() == stationIds[k]) { zaehler[k] = zaehler[k] + 1 }
      }
    }
  }
  int maxIndex = 0
  for (int k = 1; k < stationIds.length; k++) {
    if (zaehler[k] > zaehler[maxIndex]) { maxIndex = k }
  }
  return stationIds[maxIndex]
}
